mapper.select:
SELECT /* getClubDtl */

  FROM TM_CLUBXM CLUB

 WHERE CLUB.CLUB_NUMB = #{clubNumb}

  SELECT /* getActionList */
         PAGE.*
    FROM (  SELECT ROW_NUMBER() OVER (ORDER BY ACTION.HIST_NUMB DESC) AS ROW_NUMB
                 , 
              FROM TH_CLADMN ACTION

             WHERE ACTION.CLUB_NUMB = #{clubNumb}
         ) PAGE
   WHERE PAGE.ROW_NUMB BETWEEN #{startRow} AND #{endRow}
ORDER BY PAGE.ROW_NUMB

mapper.insert:
INSERT /* setClubAction */
  INTO TH_CLADMN (
       CLUB_NUMB
     , HIST_NUMB
     , ADMN_NUMB
     , ACTN_TYPE
     , BEFR_STAT
     , AFTR_STAT
     , ACTN_RSON
     , REGI_DATE
)
SELECT #{clubNumb}
     , COALESCE(MAX(ACTION.HIST_NUMB), 0) + 1
     , #{admnNumb}
     , #{actnType}
     , #{befrStat}
     , #{aftrStat}
     , #{actnRson}
     , CURRENT_TIMESTAMP(6)
  FROM TH_CLADMN ACTION
 WHERE ACTION.CLUB_NUMB = #{clubNumb}
